#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;
typedef vector<pt> pol;
typedef vector<int> vi;

const char nl = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1e9+7;
const ld EPS = 1e-10;
mt19937 rng(chrono::high_resolution_clock::now().time_since_epoch().count());

const int T = 99;
const int C = 15;

namespace Flow {
    const int N = 50*T + 2;
    const int M = 2*N*C + N + 7;

    int par[N], first[N], nxt[2*M], ep[2*M], m;
    ll flo[2*M], cap[2*M], cost[2*M];

    void init() { 
        m = 0; 
        memset(first, -1, sizeof(first)); 
        memset(flo, 0, sizeof(flo)); 
    }

    void add_edge(int a, int b, ll c=1, ll p=0) {
        nxt[m] = first[ep[m] = a];
        first[ep[m]] = m;
        cap[m] = c;
        cost[m] = p;
        ++m;

        nxt[m] = first[ep[m] = b];
        first[ep[m]] = m;
        cap[m] = 0;
        cost[m] = -p;
        ++m;
    }

    int q[N], inq[N];
    bool vis[N];
    ll pot[N], dist[N];

    void mcf_pot_init(int n) { 
        memset(pot, 0, sizeof(pot));
        for (int k = 1; k < n; ++k) 
            for (int e = 0; e < m; ++e)
                if (cap[e]) 
                    pot[ep[e^1]] = min(pot[ep[e^1]], pot[ep[e]] + cost[e]); 
    }

    ll mcf_update(int s, int t, ll& price, int n) {
        memset(vis, 0, sizeof(vis)); 
        memset(dist, INF, sizeof(dist)); 
        dist[s] = 0;
        memset(inq, -1, sizeof(inq));
        int qs = 0; 
        inq[q[qs++] = s] = 0;

        while (qs) {
            int u = q[0]; 
            inq[u] = -1;
            q[0] = q[--qs];
            if (qs) inq[q[0]] = 0;

            for (int i = 0, j = 2*i + 1, tmp; j < qs; i = j, j = 2*i + 1) {
                if (j + 1 < qs && dist[q[j + 1]] < dist[q[j]]) 
                    j++;
                if (dist[q[j]] >= dist[q[i]]) 
                    break;
                swap(q[i], q[j]);
                swap(inq[q[i]], inq[q[j]]);
            }

            if (vis[u] == 1) continue; 
            vis[u] = 1;

            for (int e = first[u]; e != -1; e = nxt[e]) { 
                int v = ep[e^1];
                if (flo[e] < cap[e] && dist[v] > dist[u] + pot[u] - pot[v] + cost[e]) {
                    dist[v] = dist[u] + pot[u] - pot[v] + cost[e];
                    par[v] = e;
                    if (inq[v] < 0) { 
                        inq[q[qs] = v] = qs; 
                        qs++; 
                    }
                    for (int i = inq[v], j = (i - 1)/2, tmp; 
                         i > 0 && dist[q[i]] < dist[q[j]]; 
                         i = j, j = (i - 1)/2) {
                        swap(q[i], q[j]);
                        swap(inq[q[i]], inq[q[j]]);
                    }
                }
            }
        }

        if (dist[t] >= INF) return 0;

        ll df = INF;
        for (int e, i = t; i != s; i = ep[e]) {
            e = par[i];
            df = min(df, cap[e] - flo[e]);
        }

        for (int e, i = t; i != s; i = ep[e]) {
            e = par[i];
            flo[e] += df;
            flo[e^1] -= df;
            price += df * cost[e];
        }

        for (int i = 0; i < n; ++i) 
            pot[i] = min((ll)INF, dist[i] + pot[i]);

        return df; 
    }
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(10);

    int n,m,k,c,d;
    cin >> n >> m >> k >> c >> d;

    const int source = 0;
    const int sink = n*T+1;
    Flow::init();

    for(int i=0; i<k; i++) {
        int a;
        cin >> a;
        Flow::add_edge(source, a, 1, 0);
    }

    for(int t=0; t<T; t++) {
        Flow::add_edge(1+t*n, sink, INF, 0);
        if(t > 0) {
            for(int i=1; i<=n; i++) {
                Flow::add_edge(i+(t-1)*n, i+t*n, INF, c);
            }
        }
    }

    for(int i=0; i<m; i++) {
        int a, b;
        cin >> a >> b;
        for(int j=0; j<C; j++) {
            int cost_val = (j+1)*(j+1) - j*j;
            for(int t=1; t<T; t++) {
                Flow::add_edge(a+(t-1)*n, b+t*n, 1, cost_val*d + c);
                Flow::add_edge(b+(t-1)*n, a+t*n, 1, cost_val*d + c);
            }
        }
    }

    Flow::mcf_pot_init(Flow::N);
    ll price = 0;
    ll flow = 0;
    while (ll df = Flow::mcf_update(source, sink, price, Flow::N)) 
        flow += df;

    assert(flow == k);
    cout << price << nl;

    return 0;
}
